/*!
 * Hammurabi Golden Gate — site.js
 * Vanilla JS, no dependencies. Progressive enhancement only:
 * every page works with JS disabled (nav links still work, the
 * contact form still submits via a normal POST to Formspree).
 */
(function () {
  "use strict";

  var $ = function (sel, ctx) { return (ctx || document).querySelector(sel); };
  var $$ = function (sel, ctx) { return Array.prototype.slice.call((ctx || document).querySelectorAll(sel)); };

  /* ------------------------------------------------------------------
   * Minimal i18n string table for the handful of messages generated by
   * JS at runtime (everything else is static text already written in
   * the right language directly in each page's HTML).
   * ------------------------------------------------------------------ */
  var LANG = document.documentElement.getAttribute("lang") === "ar" ? "ar" : "en";
  var STRINGS = {
    en: {
      playVideo: "Play background video",
      pauseVideo: "Pause background video",
      themeToLight: "Switch to light theme",
      themeToDark: "Switch to dark theme",
      sending: "Sending your message…",
      success: "Thank you — your message has been sent. We'll respond as soon as possible.",
      errorGeneric: "Something went wrong. Please try again or call us directly.",
      errorNetwork: "Network error — please try again or call us directly at +(964) 780 311 3333.",
      notConfigured: "Form endpoint not configured yet — see README.md (Formspree setup) before going live."
    },
    ar: {
      playVideo: "تشغيل الفيديو الخلفي",
      pauseVideo: "إيقاف الفيديو الخلفي",
      themeToLight: "التبديل إلى الوضع الفاتح",
      themeToDark: "التبديل إلى الوضع الداكن",
      sending: "جارٍ إرسال رسالتك…",
      success: "شكرًا لك — تم إرسال رسالتك. سنرد عليك في أقرب وقت ممكن.",
      errorGeneric: "حدث خطأ ما. يرجى المحاولة مرة أخرى أو الاتصال بنا مباشرة.",
      errorNetwork: "خطأ في الشبكة — يرجى المحاولة مرة أخرى أو الاتصال بنا مباشرة على +(964) 780 311 3333.",
      notConfigured: "لم يتم إعداد نموذج الإرسال بعد — راجع ملف README.md قبل الإطلاق."
    }
  };
  var T = STRINGS[LANG];

  /* ------------------------------------------------------------------
   * Sticky header: add a class once the user scrolls past the hero lip
   * ------------------------------------------------------------------ */
  var header = $(".site-header");
  if (header) {
    var onScrollHeader = function () {
      header.classList.toggle("is-scrolled", window.scrollY > 24);
    };
    onScrollHeader();
    window.addEventListener("scroll", onScrollHeader, { passive: true });
  }

  /* ------------------------------------------------------------------
   * Scroll progress bar
   * ------------------------------------------------------------------ */
  var progressBar = $(".scroll-progress span");
  if (progressBar) {
    var onScrollProgress = function () {
      var doc = document.documentElement;
      var max = doc.scrollHeight - doc.clientHeight;
      var pct = max > 0 ? (window.scrollY / max) * 100 : 0;
      progressBar.style.width = pct + "%";
    };
    onScrollProgress();
    window.addEventListener("scroll", onScrollProgress, { passive: true });
    window.addEventListener("resize", onScrollProgress);
  }

  /* ------------------------------------------------------------------
   * Mobile nav drawer
   * ------------------------------------------------------------------ */
  var toggle = $(".nav-toggle");
  var drawer = $(".mobile-drawer");
  if (toggle && drawer) {
    var closeBtn = $(".mobile-drawer__close", drawer);
    var backdrop = $(".mobile-drawer__backdrop", drawer);
    var openDrawer = function () {
      drawer.setAttribute("data-open", "true");
      toggle.setAttribute("aria-expanded", "true");
      document.body.style.overflow = "hidden";
      var firstLink = $("a", drawer);
      if (firstLink) firstLink.focus({ preventScroll: true });
    };
    var closeDrawer = function () {
      drawer.setAttribute("data-open", "false");
      toggle.setAttribute("aria-expanded", "false");
      document.body.style.overflow = "";
      toggle.focus({ preventScroll: true });
    };
    toggle.addEventListener("click", openDrawer);
    if (closeBtn) closeBtn.addEventListener("click", closeDrawer);
    if (backdrop) backdrop.addEventListener("click", closeDrawer);
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && drawer.getAttribute("data-open") === "true") closeDrawer();
    });
    $$("a", drawer).forEach(function (a) { a.addEventListener("click", closeDrawer); });
  }

  /* ------------------------------------------------------------------
   * Scroll reveal via IntersectionObserver (falls back to instantly
   * visible if unsupported, and is skipped entirely for reduced motion)
   * ------------------------------------------------------------------ */
  var prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var revealEls = $$("[data-reveal]");
  if (revealEls.length) {
    if (prefersReducedMotion || !("IntersectionObserver" in window)) {
      revealEls.forEach(function (el) { el.classList.add("is-visible"); });
    } else {
      // stagger children of groups
      $$("[data-reveal-group]").forEach(function (group) {
        $$("[data-reveal]", group).forEach(function (el, i) {
          el.style.setProperty("--i", i);
        });
      });
      var io = new IntersectionObserver(
        function (entries) {
          entries.forEach(function (entry) {
            if (entry.isIntersecting) {
              entry.target.classList.add("is-visible");
              io.unobserve(entry.target);
            }
          });
        },
        { threshold: 0.14, rootMargin: "0px 0px -8% 0px" }
      );
      revealEls.forEach(function (el) { io.observe(el); });
    }
  }

  /* ------------------------------------------------------------------
   * Video showcase play/pause toggle
   * ------------------------------------------------------------------ */
  $$(".video-showcase").forEach(function (wrap) {
    var vid = $("video", wrap);
    var btn = $(".play-toggle", wrap);
    if (!vid || !btn) return;
    var playIcon = btn.querySelector('[data-icon="play"]');
    var pauseIcon = btn.querySelector('[data-icon="pause"]');
    var sync = function () {
      var playing = !vid.paused && !vid.ended;
      if (playIcon) playIcon.style.display = playing ? "none" : "block";
      if (pauseIcon) pauseIcon.style.display = playing ? "block" : "none";
      btn.setAttribute("aria-label", playing ? T.pauseVideo : T.playVideo);
    };
    btn.addEventListener("click", function () {
      if (vid.paused) vid.play(); else vid.pause();
    });
    vid.addEventListener("play", sync);
    vid.addEventListener("pause", sync);
    sync();
  });

  /* ------------------------------------------------------------------
   * Light / dark theme toggle
   * The initial theme is already set by a blocking inline script in
   * <head> (before paint, no flash-of-wrong-theme). This just wires up
   * the toggle button(s) — there's one in the desktop header and one
   * in the mobile drawer, kept in sync — and persists the choice.
   * ------------------------------------------------------------------ */
  var themeToggles = $$(".theme-toggle");
  var themeColorMeta = $("#theme-color-meta");
  if (themeToggles.length) {
    var applyThemeChrome = function (theme) {
      themeToggles.forEach(function (btn) {
        btn.setAttribute("aria-label", theme === "light" ? T.themeToDark : T.themeToLight);
      });
      if (themeColorMeta) themeColorMeta.setAttribute("content", theme === "light" ? "#FAF7EF" : "#14120F");
    };

    var setTheme = function (theme) {
      document.documentElement.setAttribute("data-theme", theme);
      try { localStorage.setItem("hgg-theme", theme); } catch (err) { /* private mode, ignore */ }
      applyThemeChrome(theme);
    };

    // Sync button labels/meta to whatever the inline head script already set.
    applyThemeChrome(document.documentElement.getAttribute("data-theme") || "dark");

    themeToggles.forEach(function (btn) {
      btn.addEventListener("click", function () {
        var current = document.documentElement.getAttribute("data-theme") === "light" ? "light" : "dark";
        setTheme(current === "dark" ? "light" : "dark");
      });
    });

    // If the person hasn't explicitly chosen a theme on this site yet,
    // keep following their OS-level preference live.
    if (window.matchMedia) {
      var mq = window.matchMedia("(prefers-color-scheme: light)");
      var onSystemChange = function (e) {
        var hasSavedChoice = false;
        try { hasSavedChoice = localStorage.getItem("hgg-theme") !== null; } catch (err) { hasSavedChoice = false; }
        if (!hasSavedChoice) {
          document.documentElement.setAttribute("data-theme", e.matches ? "light" : "dark");
          applyThemeChrome(e.matches ? "light" : "dark");
        }
      };
      if (mq.addEventListener) mq.addEventListener("change", onSystemChange);
    }
  }

  /* ------------------------------------------------------------------
   * Contact form — progressive enhancement over a plain POST.
   * Without JS: normal <form action="https://formspree.io/f/XXXX" method="POST">
   * submit, Formspree redirects to a thank-you page.
   * With JS: fetch() intercepts submit, shows inline success/error state,
   * and the page never navigates away.
   * ------------------------------------------------------------------ */
  var form = $("#contact-form");
  if (form) {
    var status = $(".form-status", form);
    var submitBtn = $('button[type="submit"]', form);

    var setStatus = function (state, message) {
      if (!status) return;
      status.textContent = message;
      status.setAttribute("data-state", state);
    };

    form.addEventListener("submit", function (e) {
      // Honeypot: if the hidden field got filled in, silently drop it.
      var hp = form.querySelector('input[name="_gotcha"]');
      if (hp && hp.value) {
        e.preventDefault();
        return;
      }

      // If the endpoint is still the placeholder, let it fail loudly in
      // dev but don't break the page — this check is safe to delete once
      // a real Formspree/Web3Forms endpoint is wired in.
      var action = form.getAttribute("action") || "";
      if (action.indexOf("YOUR_FORM_ID") !== -1) {
        e.preventDefault();
        setStatus("error", T.notConfigured);
        return;
      }

      e.preventDefault();
      setStatus("loading", T.sending);
      if (submitBtn) submitBtn.disabled = true;

      fetch(action, {
        method: "POST",
        body: new FormData(form),
        headers: { Accept: "application/json" },
      })
        .then(function (res) {
          if (res.ok) {
            setStatus("success", T.success);
            form.reset();
          } else {
            return res.json().then(function (data) {
              var msg = (data && data.errors && data.errors.map(function (e) { return e.message; }).join(", ")) || T.errorGeneric;
              setStatus("error", msg);
            });
          }
        })
        .catch(function () {
          setStatus("error", T.errorNetwork);
        })
        .finally(function () {
          if (submitBtn) submitBtn.disabled = false;
        });
    });
  }

  /* ------------------------------------------------------------------
   * Lightweight consent notice (optional — no analytics/ad trackers are
   * loaded by this site at all, so strictly there's nothing to consent
   * to yet. This is included, off by default, in case the client later
   * adds analytics; delete this block plus the .consent-bar element in
   * every page if it's not needed.)
   * ------------------------------------------------------------------ */
  var consentBar = $(".consent-bar");
  if (consentBar) {
    var KEY = "hgg_consent_ack";
    var already = false;
    try { already = localStorage.getItem(KEY) === "1"; } catch (err) { already = false; }
    if (!already) {
      window.setTimeout(function () { consentBar.setAttribute("data-visible", "true"); }, 900);
    }
    var ack = function () {
      consentBar.setAttribute("data-visible", "false");
      try { localStorage.setItem(KEY, "1"); } catch (err) { /* private mode, ignore */ }
    };
    $$("[data-consent-ack]", consentBar).forEach(function (btn) {
      btn.addEventListener("click", ack);
    });
  }

  /* ------------------------------------------------------------------
   * Current year in footer
   * ------------------------------------------------------------------ */
  $$("[data-year]").forEach(function (el) { el.textContent = new Date().getFullYear(); });
})();
